<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { api } from './services/api'
import { ElButton, ElButtonGroup, ElDialog, ElForm, ElFormItem, ElInput, ElOption, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'

type DocumentRow = { id: string; resourceId?: string; title: string; type: string; status: string; author: string; version: string; updated: string }
const documents = ref<DocumentRow[]>([]); const selectedId = ref<string | null>(null); const query = ref(''); const status = ref('全部'); const editorTitle = ref(''); const editorContent = ref(''); const saving = ref(false); const saved = ref(false); const publishConfirm = ref(false); const toast = ref(''); const workingVersion = ref(0); let saveTimer: number | undefined
const selected = computed(() => documents.value.find(item => item.id === selectedId.value)); const filtered = computed(() => documents.value.filter(item => `${item.title} ${item.type} ${item.author}`.toLowerCase().includes(query.value.toLowerCase()) && (status.value === '全部' || item.status === status.value)))
function notify(message: string) { toast.value = message; window.setTimeout(() => toast.value = '', 2400) }
const actorId = String(import.meta.env.VITE_ACTOR_ID || '')
async function loadDocuments() { if (!actorId) { notify('未配置当前用户身份，无法加载文档'); return } try { const result = await api.listDocuments(actorId); documents.value = result.map(item => ({ id: item.id, resourceId: item.resourceId || item.resource_id, title: `Document ${item.id.slice(0, 8)}`, type: item.kind === 'ARTICLE' ? '文章' : item.kind === 'NOTE' ? '笔记' : '文档', status: item.currentRevisionId || item.current_revision_id ? '草稿' : '未开始', author: '当前用户', version: item.currentRevisionId || item.current_revision_id ? '已创建版本' : 'v1', updated: '刚刚' })) } catch { documents.value = []; notify('文档 API 加载失败，请检查后端服务') } }
async function hydrateDocumentTitles() { if (!actorId) return; await Promise.all(documents.value.filter(item => item.resourceId).map(async item => { try { const resource = await api.getResource(item.resourceId!, actorId); if (resource.title) item.title = resource.title } catch { /* 无资源读取权限时保持脱敏 ID */ } })) }
async function openDocument(item: DocumentRow) { if (item.id.startsWith('new-')) { if (!actorId) { notify('未配置当前用户身份，无法创建文档'); return }; try { const created = await api.createDocument({ title: item.title, kind: 'DOCUMENT', locale: 'zh-CN', content: '' }, actorId); item = { ...item, id: created.id, resourceId: created.resourceId || created.resource_id }; documents.value.unshift(item); notify('文档已创建') } catch (error) { notify(error instanceof Error ? error.message : '文档创建失败'); return } }; if (!documents.value.some(document => document.id === item.id)) documents.value.unshift(item); selectedId.value = item.id; editorTitle.value = item.title; editorContent.value = ''; workingVersion.value = 0; if (actorId) { try { const copy = await api.getWorkingCopy(item.id, actorId); editorContent.value = copy.content || ''; workingVersion.value = copy.version || 0 } catch { notify('工作副本加载失败') } } saved.value = true }
function scheduleSave() { saved.value = false; saving.value = true; if (saveTimer) window.clearTimeout(saveTimer); saveTimer = window.setTimeout(() => { saving.value = false; saved.value = true; notify('草稿已自动保存') }, 650) }
async function saveNow() { if (!actorId || !selectedId.value) { notify('未配置当前用户身份，无法保存文档'); return }; saving.value = true; try { const copy = await api.updateWorkingCopy(selectedId.value, { content: editorContent.value, contentSchemaVersion: 'markdown-v1', expectedVersion: workingVersion.value }, actorId); workingVersion.value = copy.version ?? workingVersion.value + 1; saved.value = true; notify('工作副本已保存') } catch { notify('工作副本保存失败，请重试') } finally { saving.value = false } }
async function publish() { const item = selected.value; if (!item || !actorId) { notify('未配置当前用户身份，无法发布文档'); return }; saving.value = true; try { const revision = await api.commitDocumentRevision(item.id, { content: editorContent.value, contentSchemaVersion: 'markdown-v1', expectedVersion: workingVersion.value }, actorId); const revisionNumber = revision.revisionNumber ?? revision.revision_number; if (typeof revisionNumber !== 'number') throw new Error('版本号不可用'); await api.publishDocument(item.id, { slug: `document-${item.id.slice(0, 8)}`, revisionNumber }, actorId); item.status = '已发布'; item.title = editorTitle.value || item.title; item.updated = new Date().toLocaleString('zh-CN'); workingVersion.value += 1; publishConfirm.value = false; saved.value = true; notify('文档已发布并写入审计') } catch (error) { notify(error instanceof Error ? error.message : '文档发布失败') } finally { saving.value = false } }
watch([editorTitle, editorContent], () => { if (selectedId.value) scheduleSave() }); onBeforeUnmount(() => { if (saveTimer) window.clearTimeout(saveTimer) }); loadDocuments().then(hydrateDocumentTitles)
</script>

<template><div class="document-shell"><header class="catalog-topbar"><div class="catalog-brand"><span class="brand-mark">i</span><strong>Ikaros <small>Console</small></strong></div><span class="catalog-context">内容与创作 · 文章与文档</span><span class="mini-avatar">陈</span></header><main class="document-main"><section v-if="!selectedId" class="document-list-view"><div class="catalog-heading"><div><p class="eyebrow">内容与创作</p><h1>文章与文档</h1><p>管理草稿、发布版本与归档内容。</p></div><el-button type="primary" @click="openDocument({ id: `new-${Date.now()}`, title: '未命名文档', type: '文档', status: '草稿', author: '陈昊', version: 'v1', updated: '刚刚' })">＋ 新建</el-button></div><div class="document-toolbar surface-card"><el-input v-model="query" clearable placeholder="搜索标题或作者" style="max-width:360px" /><el-button-group><el-button v-for="value in ['全部','草稿','已发布','已归档']" :key="value" :type="status === value ? 'primary' : 'default'" @click="status = value">{{ value }}</el-button></el-button-group></div><section class="document-table surface-card"><el-table :data="filtered" stripe empty-text="没有匹配文档"><el-table-column prop="title" label="标题" min-width="220" /><el-table-column prop="type" label="类型" width="100" /><el-table-column label="状态" width="110"><template #default="{ row }"><el-tag :type="row.status === '草稿' ? 'warning' : row.status === '已归档' ? 'info' : 'success'">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="author" label="作者" width="110" /><el-table-column prop="version" label="版本" width="100" /><el-table-column prop="updated" label="最近更新" width="160" /><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openDocument(row)">编辑</el-button></template></el-table-column></el-table></section></section><section v-else class="editor-view"><div class="editor-top"><el-button link @click="selectedId = null">← 返回列表</el-button><div class="editor-save-state"><el-tag :type="saving ? 'warning' : saved ? 'success' : 'info'">{{ saving ? '正在保存…' : saved ? '已保存' : '离线修改' }}</el-tag><el-button @click="saveNow">⌘ S 保存</el-button><el-button type="primary" @click="publishConfirm = true">发布</el-button></div></div><div class="editor-layout"><article class="editor-canvas surface-card"><el-input v-model="editorTitle" class="editor-title-input" placeholder="未命名文档" /><div class="editor-toolbar"><el-button-group><el-button>粗体</el-button><el-button>斜体</el-button><el-button>链接</el-button><el-button>Markdown</el-button></el-button-group></div><el-input v-model="editorContent" class="editor-content" type="textarea" :rows="18" placeholder="开始写作…" /></article><aside class="editor-sidebar surface-card"><h2>文档属性</h2><el-form label-position="top"><el-form-item label="内容类型"><el-select model-value="文档"><el-option label="文档" value="文档" /><el-option label="文章" value="文章" /></el-select></el-form-item><el-form-item label="状态"><el-select v-model="selected!.status"><el-option label="草稿" value="草稿" /><el-option label="已发布" value="已发布" /><el-option label="已归档" value="已归档" /></el-select></el-form-item><el-form-item label="Slug / 公开标识"><el-input placeholder="可选" /></el-form-item></el-form><div class="editor-note"><span>i</span><p>编辑器变更会自动保存为新版本；发布前会明确可见性与发布时间。</p></div></aside></div></section></main><el-dialog v-model="publishConfirm" title="发布此文档？" width="420px"><p class="review-copy">发布后当前版本将对授权读者可见，历史版本不会被删除。</p><div class="dialog-actions"><el-button @click="publishConfirm = false">取消</el-button><el-button type="primary" @click="publish">确认发布</el-button></div></el-dialog><div v-if="toast" class="snackbar">✓ {{ toast }}<button @click="toast = ''">×</button></div></div></template>
